insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-10-02','opgelost','Offertes','Offerte of interne begroting maken lukt weer bij oude voorwaarden',
   'Stonden er op een calculatie algemene voorwaarden die inmiddels zijn verwijderd, dan gebeurde er niets als je een offerte of interne begroting wilde maken. EVA vraagt je nu eerst de voorwaarden opnieuw te kiezen, en laat een melding zien als het aanmaken toch mislukt.');
